const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeMeadPoint = ee.Geometry.Point(-114.364, 36.101); // Approximate center of Lake Mead
  const scale = 30; // Native Landsat resolution for water extent is fine, but for regional area reduction, use a coarser scale for speed. 100m for area calculation to balance accuracy and speed.

  // Date ranges
  const date2000_start = '2000-07-01';
  const date2000_end = '2000-07-11'; // +/- 5 days for robust image finding

  const date2022_start = '2022-06-28';
  const date2022_end = '2022-07-08'; // +/- 5 days for robust image finding

  // 2. Data Acquisition & Pre-processing Functions

  // Function to mask clouds for Landsat 7 (Tier 1 Surface Reflectance)
  function maskL7Clouds(image) {
    const qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud shadow and clouds, respectively.
    // Bit 6 is water, Bit 7 is snow/ice. We are interested in water, so don't mask it out.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, and designated fill pixels.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0))
                 .and(qa.eq(672) // 32 + 64 + 576 water, cloud confidence low, cloud shadow confidence low
                      .or(qa.eq(0)) // clear
                      .or(qa.eq(688)) // water, cloud confidence high, cloud shadow confidence low
                      .or(qa.eq(704)) // water, cloud confidence low, cloud shadow confidence high
                      .or(qa.eq(720)) // water, cloud confidence high, cloud shadow confidence high
                      .or(qa.eq(320)) // water, cloud confidence low, cloud shadow confidence low
                      .or(qa.eq(384)) // water, cloud confidence high, cloud shadow confidence low
                      .or(qa.eq(448)) // water, cloud confidence low, cloud shadow confidence high
                      .or(qa.eq(512)) // water, cloud confidence high, cloud shadow confidence high
                 );
    return image.updateMask(mask).select(['B1', 'B2', 'B3', 'B4', 'B5', 'B7']);
  }

  // Function to mask clouds for Landsat 8/9 (Tier 2 Surface Reflectance)
  function maskL8L9Clouds(image) {
    const qa = image.select('QA_PIXEL');
    // Bits 3, 4, 5 are cloud shadow, snow, clouds respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    // Also mask out high cloud confidence to be safe.
    const cirrus_mask = qa.bitwiseAnd(1 << 8).eq(0); // Cirrus bit (L8 only)
    const high_cloud_confidence_mask = qa.bitwiseAnd(1 << 11).eq(0); // High confidence cloud

    return image.updateMask(mask.and(cirrus_mask).and(high_cloud_confidence_mask))
                .select(['B2', 'B3', 'B4', 'B5', 'B6', 'B7']);
  }

  // Function to calculate MNDWI for Landsat 7 (Green B2, SWIR1 B5)
  function calculateMNDWI_L7(image) {
    return image.normalizedDifference(['B2', 'B5']).rename('MNDWI');
  }

  // Function to calculate MNDWI for Landsat 8/9 (Green B3, SWIR1 B6)
  function calculateMNDWI_L8L9(image) {
    return image.normalizedDifference(['B3', 'B6']).rename('MNDWI');
  }

  // Generic function to process a collection
  async function processCollection(collection, dateStart, dateEnd, cloudMaskFn, mndwiFn, sensor) {
    let filteredCollection = collection
      .filterBounds(lakeMeadPoint)
      .filterDate(dateStart, dateEnd);

    const collectionSize = await filteredCollection.size().getInfo();
    console.log(`${sensor} Images (${dateStart} to ${dateEnd}): ${collectionSize}`);

    if (collectionSize === 0) {
      console.log(`No images found for ${sensor} in the specified date range.`);
      return {image: null, cloud_perc: null, valid_pixels: 0};
    }

    // Apply cloud mask and MNDWI calculation
    filteredCollection = filteredCollection.map(image => cloudMaskFn(image));

    // Get the least cloudy image
    const image = await filteredCollection
      .sort('CLOUD_COVER', false) // Descending, so least cloudy images have higher values if no clouds
      .sort('CLOUD_COVER_LAND', false) // Or cloud cover over land if available
      .first();

    if (!image) { // If all images were completely masked out
      console.log(`No valid (unmasked) image found for ${sensor} after cloud masking.`);
      return {image: null, cloud_perc: null, valid_pixels: 0};
    }

    const cloudCover = image.get('CLOUD_COVER').getInfo();
    let cloudCoverPrint = cloudCover !== null ? `${cloudCover.toFixed(2)}%` : 'N/A';

    const mndwi = mndwiFn(image);
    const waterMask = mndwi.gt(0); // MNDWI > 0 is typically water
    const waterPixels = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeMeadPoint.buffer(50000), // Buffer to cover most of Lake Mead
      scale: 30, // Use native resolution for pixel count
      maxPixels: 1e9,
      tileScale: 16
    }).get('MNDWI');

    const validPixelsCount = await waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lakeMeadPoint.buffer(50000),
      scale: 30,
      maxPixels: 1e9,
      tileScale: 16
    }).get('MNDWI').getInfo();

    console.log(`${sensor} - Selected Image Cloud Cover: ${cloudCoverPrint}, Valid Pixels: ${validPixelsCount}`);

    return {
      image: waterMask,
      cloud_perc: cloudCover,
      valid_pixels: validPixelsCount,
      mndwi_image: mndwi
    };
  }

  // --- 2000 Data Acquisition & Processing ---
  const l7Collection = ee.ImageCollection('LANDSAT/LE07/C01/T1_SR');
  const result2000 = await processCollection(l7Collection, date2000_start, date2000_end, maskL7Clouds, calculateMNDWI_L7, 'Landsat 7');

  if (!result2000.image) {
    console.log("No valid Landsat 7 image or pixels for 2000.");
    console.log("C1");
    return;
  }
  if (result2000.valid_pixels === 0) {
    console.log("No valid pixels for 2000 after cloud masking/processing.");
    console.log("C2");
    return;
  }

  // --- 2022 Data Acquisition & Processing ---
  const l8Collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR'); // Prefer C02 for L8
  const result2022 = await processCollection(l8Collection, date2022_start, date2022_end, maskL8L9Clouds, calculateMNDWI_L8L9, 'Landsat 8');

  if (!result2022.image) {
    console.log("No valid Landsat 8 image or pixels for 2022.");
    console.log("C1");
    return;
  }
  if (result2022.valid_pixels === 0) {
    console.log("No valid pixels for 2022 after cloud masking/processing.");
    console.log("C2");
    return;
  }

  // 3. Calculation of Water Extent (Area)
  const lakeMeadArea = lakeMeadPoint.buffer(50000); // 50km buffer around point to cover lake

  const calculateWaterArea = async (waterMaskImage, year) => {
    const area = waterMaskImage.multiply(ee.Image.pixelArea())
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: lakeMeadArea,
        scale: scale, // Use coarser scale for area calculation to avoid memory issues
        maxPixels: 1e9,
        tileScale: 16
      }).get('MNDWI'); // The band will be named MNDWI because that's what the waterMask uses.

    const areaSqMeters = await area.getInfo();
    if (areaSqMeters === null || isNaN(areaSqMeters)) {
      console.log(`Error: Area calculation failed for ${year}.`);
      return null;
    }
    return areaSqMeters / 1e6; // Convert square meters to square kilometers
  };

  const waterArea2000 = await calculateWaterArea(result2000.image, 2000);
  const waterArea2022 = await calculateWaterArea(result2022.image, 2022);

  if (waterArea2000 === null || waterArea2022 === null) {
    console.log("C3"); // Calculation Failure
    return;
  }

  console.log(`Lake Mead Water Extent (2000): ${waterArea2000.toFixed(2)} sq km`);
  console.log(`Lake Mead Water Extent (2022): ${waterArea2022.toFixed(2)} sq km`);

  // 4. Comparison and Final Answer
  if (waterArea2022 < waterArea2000) {
    console.log("A"); // Yes, the surface water extent decreased
  } else {
    console.log("B"); // No, the surface water extent did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
